'use strict';

function isValidCandidate(value) {
  if (!value || typeof value !== 'object' || typeof value.title !== 'string' || !value.title.trim()) {
    return false;
  }
  if (typeof value.url !== 'string') return false;
  try {
    const parsed = new URL(value.url);
    return parsed.protocol === 'http:' || parsed.protocol === 'https:';
  } catch {
    return false;
  }
}

function full(candidate) {
  const summary = typeof candidate.summary === 'string' ? candidate.summary : '';
  return `${candidate.title}\n${candidate.url}\n${summary}`;
}

function interpretLookup(command, candidates) {
  if (typeof command !== 'string' || !Array.isArray(candidates)) return 'Invalid command.';

  const match = command.match(/^\/(find|brief|pick:(\d+))\s+(.\S*(?:\s.*)?)$/);
  if (!match || !match[3].trim()) return 'Invalid command.';

  const mode = match[1];
  const limit = match[2] === undefined ? null : Number(match[2]);
  if (limit !== null && (!Number.isSafeInteger(limit) || limit < 1)) return 'Invalid command.';

  const valid = candidates.filter(isValidCandidate).slice(0, 50);
  if (valid.length === 0) return 'No results.';

  if (mode === 'brief') {
    return valid.map((item) => `${item.title} — ${item.url}`).join('\n');
  }
  if (mode.startsWith('pick:')) {
    return limit <= valid.length ? full(valid[limit - 1]) : 'No results.';
  }
  return valid.map(full).join('\n\n');
}

module.exports = { interpretLookup };

