'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['interpretLookup']);
const { interpretLookup } = api;

const candidates = [
  { title: 'Alpha', url: 'https://example.com/a', summary: 'First' },
  { title: '', url: 'https://example.com/empty', summary: 'ignored' },
  { title: 'Bad URL', url: '/relative', summary: 'ignored' },
  { title: 'Beta', url: 'http://example.org/b', summary: 42 },
  { title: 'Gamma', url: 'https://example.com/g?q=1', summary: '' }
];
const snapshot = candidates.map(candidate => ({ ...candidate }));

assert.strictEqual(
  interpretLookup('/find anything', candidates),
  'Alpha\nhttps://example.com/a\nFirst\n\nBeta\nhttp://example.org/b\n\n\nGamma\nhttps://example.com/g?q=1\n'
);
assert.strictEqual(
  interpretLookup('/brief anything', candidates),
  'Alpha — https://example.com/a\nBeta — http://example.org/b\nGamma — https://example.com/g?q=1'
);
assert.strictEqual(
  interpretLookup('/pick:2 anything', candidates),
  'Beta\nhttp://example.org/b\n'
);
assert.strictEqual(interpretLookup('/pick:4 anything', candidates), 'No results.');
assert.deepStrictEqual(candidates, snapshot);

assert.strictEqual(interpretLookup('/find q', []), 'No results.');
assert.strictEqual(
  interpretLookup('/brief q', [null, 1, {}, { title: 'x', url: 'ftp://example.com' }]),
  'No results.'
);
assert.strictEqual(
  interpretLookup('/pick:1 q', [{ title: 'x', url: 'not a url' }]),
  'No results.'
);

const fiftyOne = Array.from({ length: 51 }, (_, index) => ({
  title: `T${index + 1}`,
  url: `https://example.com/${index + 1}`,
  summary: `S${index + 1}`
}));
assert.strictEqual(
  interpretLookup('/pick:50 q', fiftyOne),
  'T50\nhttps://example.com/50\nS50'
);
assert.strictEqual(interpretLookup('/pick:51 q', fiftyOne), 'No results.');

const validOnlyAfterWindow = Array.from({ length: 51 }, (_, index) =>
  index < 50
    ? { title: '', url: `https://example.com/${index}` }
    : { title: 'Late', url: 'https://example.com/late', summary: 'ignored' }
);
assert.strictEqual(interpretLookup('/find q', validOnlyAfterWindow), 'No results.');

for (const command of [
  null,
  undefined,
  1,
  '',
  ' ',
  '/find',
  '/find   ',
  '/brief',
  '/pick:1',
  '/pick:0 q',
  '/pick:-1 q',
  '/pick:+1 q',
  '/pick:1.5 q',
  '/pick:01x q',
  '/pick: q',
  '/unknown q',
  'find q'
]) {
  assert.strictEqual(interpretLookup(command, []), 'Invalid command.');
}

assert.strictEqual(interpretLookup('/find q', null), 'Invalid command.');
assert.strictEqual(interpretLookup('/brief q', {}), 'Invalid command.');
assert.strictEqual(interpretLookup('/pick:1 q', 'no'), 'Invalid command.');

